def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}

    # Cover the shape with 2x2 squares and L-triominoes. Color 2x2 squares
    # with 1. L colors distinguish the missing corner: TL=2, TR=4, BL=3, BR=2.
    shapes = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            shapes.append((set(box), 1))
            for missing, color in enumerate((2, 4, 3, 2)):
                shapes.append((set(box[:missing] + box[missing + 1:]), color))

    by_cell = {p: [] for p in cells}
    for shape, color in shapes:
        if shape <= cells:
            for p in shape:
                by_cell[p].append((shape, color))

    solution = None
    def cover(remaining, placed):
        nonlocal solution
        if not remaining:
            solution = placed
            return True
        p = min(remaining, key=lambda q: sum(shape <= remaining for shape, _ in by_cell[q]))
        for shape, color in sorted((x for x in by_cell[p] if x[0] <= remaining),
                                   key=lambda x: (-len(x[0]), x[1])):
            if cover(remaining - shape, placed + [(shape, color)]):
                return True
        return False

    cover(cells, [])
    out = [[0] * w for _ in range(h)]
    if solution is not None:
        for shape, color in solution:
            for r, c in shape:
                out[r][c] = color
    return out
